int pqcp_channel_policy_lookup(
	enum pqcp_channel_policy_state state,
	enum pqcp_channel_control_kind control,
	struct pqcp_channel_policy_decision *decision)
{
	if (state < PQCP_CHANNEL_POLICY_NEW ||
	    state >= PQCP_CHANNEL_POLICY_STATE_COUNT ||
	    control < PQCP_CHANNEL_CONTROL_NONE ||
	    control >= PQCP_CHANNEL_CONTROL_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = channel_catalog[state][control];
	return 0;
}

int pqcp_channel_policy_catalog_audit(void)
{
	for (size_t state = 0U;
	     state < PQCP_CHANNEL_POLICY_STATE_COUNT; ++state) {
		for (size_t control = 0U;
		     control < PQCP_CHANNEL_POLICY_CONTROL_COUNT;
		     ++control) {
			const struct pqcp_channel_policy_decision *entry =
				&channel_catalog[state][control];

			if ((size_t)entry->state != state ||
			    (size_t)entry->control != control ||
			    entry->action >
				PQCP_CHANNEL_POLICY_CLOSE_ON_FAILURE ||
			    entry->next_state < PQCP_CHANNEL_POLICY_NEW ||
			    entry->next_state >
				PQCP_CHANNEL_POLICY_TERMINATED) {
				return -EBADMSG;
			}
			if (entry->action == PQCP_CHANNEL_POLICY_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}

